import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.B0lbOe_c.js";var o=JSON.parse(`{"title":"Sichtbarkeit von Eigenschaften","description":"","frontmatter":{"title":"Sichtbarkeit von Eigenschaften","covers":{"screens":["SCR-032","SCR-040"],"stories":["US-075","US-076","US-098","US-124","US-125","US-126","US-127","US-128"]}},"headers":[],"relativePath":"de/administration/property-visibility.md","filePath":"de/administration/property-visibility.md"}`),s={name:`de/administration/property-visibility.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="sichtbarkeit-von-eigenschaften" tabindex="-1">Sichtbarkeit von Eigenschaften <a class="header-anchor" href="#sichtbarkeit-von-eigenschaften" aria-label="Permalink to “Sichtbarkeit von Eigenschaften”">​</a></h1><p>Manche Eigenschaften sollen nicht alle sehen, die eine Entität lesen dürfen, etwa Investitionskosten oder eine Sicherheitseinstufung. Die Sicherheitsadministration legt für jede Eigenschaft fest, wer ihre Werte sehen und schreiben darf. Du brauchst die Rolle <code>security-admin</code> (Berechtigung <code>visibility:configure</code>); Metamodell-Administratoren können die Sichtbarkeit nicht ändern (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>).</p><h2 id="was-die-sichtbarkeit-bewirkt" tabindex="-1">Was die Sichtbarkeit bewirkt <a class="header-anchor" href="#was-die-sichtbarkeit-bewirkt" aria-label="Permalink to “Was die Sichtbarkeit bewirkt”">​</a></h2><ul><li><strong>Rollenbasierte</strong> Eigenschaften werden in Katalogen, im Portal und beim Schreiben von Entitäten durchgesetzt: <ul><li>Ohne Leserolle zeigt eine Spalte zur Eigenschaft ein Schloss und leere Zellen und lässt sich weder sortieren noch filtern.</li><li>Ohne Schreibrolle wird ein Batch oder eine Verbindung, die ihren Wert setzt oder entfernt, mit <code>403</code> abgelehnt.</li><li>Alte und neue Werte einer solchen Eigenschaft werden verschlüsselt im Audit-Log gespeichert.</li></ul></li><li><strong>Verbindungsbasierte</strong> Eigenschaften werden auf denselben Kanälen pro Entität durchgesetzt: <ul><li>Eine Person sieht und schreibt den Wert nur bei Entitäten, die über den gewählten Verbindungstyp mit dem Element verbunden sind, das mit ihrem Konto verknüpft ist, in beide Richtungen und über eine Verbindung (siehe <a href="#person-metatype">Der Entitätstyp von Personen</a>).</li><li>In einem Katalog zeigt die Spalte den Wert in den Zeilen solcher Entitäten und in allen anderen eine leere Zelle. Sortierung und Filter behandeln die leeren Zellen wie Einträge ohne Wert, so hängt das Ergebnis nie von einem verborgenen Wert ab.</li><li>Ohne verknüpftes Element oder für das lokale Systemadministrator-Konto verhält sich die Spalte wie eine rollenbasierte Spalte ohne Leserolle.</li><li>Ein Batch oder eine Verbindung, die den Wert einer Entität außerhalb des Bereichs oder einer im selben Batch angelegten Entität setzt oder entfernt, wird mit <code>403</code> abgelehnt; lege zuerst die Verbindung an, die den Bereich festlegt.</li><li>Eine neue oder entfernte Verbindung dieses Typs gilt ab der nächsten Anfrage.</li></ul></li><li><strong>Override-Rollen</strong> lesen jede Eigenschaft, unabhängig von ihrer Sichtbarkeit (siehe <a href="#override-roles">Override-Rollen</a>). Sonst niemand: Weder <code>system-admin</code> noch <code>security-admin</code> lesen eingeschränkte Werte ohne Leserolle.</li></ul><h2 id="die-seite" tabindex="-1">Die Seite <a class="header-anchor" href="#die-seite" aria-label="Permalink to “Die Seite”">​</a></h2><p>Öffne <em>Sichtbarkeit von Eigenschaften</em> in der Kopfzeile. Die Seite listet jede Eigenschaft mit den Entitätstypen, die sie verwenden, ihrer Sichtbarkeit und ihrer Einschränkung; eingeschränkte Eigenschaften tragen das Badge <em>Eingeschränkt</em>. Filtere die Liste nach Name.</p>`,6),i(d,{name:`property-visibility`,alt:`Dialog für die Sichtbarkeit einer Eigenschaft mit Lese- und Schreibrollen`}),o[1]||=t(`<h2 id="person-metatype" tabindex="-1">Der Entitätstyp von Personen <a class="header-anchor" href="#person-metatype" aria-label="Permalink to “Der Entitätstyp von Personen”">​</a></h2><p>Verbindungsbasierte Sichtbarkeit geht von dem Element aus, das eine Person im Modell darstellt, zum Beispiel einem <em>Business Actor</em>. Wähle diesen Entitätstyp in <em>Entitätstyp von Personen</em> oberhalb der Liste; <em>Keiner</em> schaltet verbindungsbasierte Sichtbarkeit für alle ab. Wählbar sind nur Entitätstypen, die keine Verbindungstypen sind, und ein hier verwendeter Entitätstyp lässt sich nicht löschen. Die Änderung wird als <code>visibility.person-metatype-changed</code> ins Audit-Log geschrieben.</p><p>Solange es verbindungsbasierte Eigenschaften gibt, aber kein Entitätstyp gesetzt ist, zeigt die Seite eine Warnung: Die Werte dieser Eigenschaften sieht niemand.</p><p>Das Konto einer Person wird über die API mit ihrem Element verknüpft (siehe <a href="./identity-providers#link-an-account-to-an-element">Identity-Provider und Personen</a>). Eine Verknüpfung zählt nur, solange das Element existiert und vom gewählten Entitätstyp oder einem seiner Untertypen ist; ein Wechsel des Entitätstyps behält die Verknüpfungen, aber Verknüpfungen zu Elementen eines anderen Typs zählen nicht mehr.</p><h2 id="account-mapping" tabindex="-1">Konto-Zuordnung <a class="header-anchor" href="#account-mapping" aria-label="Permalink to “Konto-Zuordnung”">​</a></h2><p>Neben der manuellen Verknüpfung kann ein Konto <strong>über eine Eigenschaft</strong> mit seinem Personenelement verknüpft werden: dem Element, dessen Wert einer gewählten <em>Text</em>-Eigenschaft einem Attribut des Kontos entspricht. Neben dem Entitätstyp von Personen legt die <em>Konto-Zuordnung</em> die Eigenschaft (eine Texteigenschaft des Entitätstyps von Personen, etwa <em>Account ID</em> des <a href="./metamodel-packages#organization-package">Organisations-Pakets</a>) und das Attribut fest: die <strong>E-Mail-Adresse</strong> (ohne Beachtung der Groß- und Kleinschreibung) oder das <strong>IdP-Subject</strong> einer Identitätsbindung des Kontos. Mitarbeiter-ID und externe Referenz folgen mit der Bereitstellung, die sie füllt. Mit <em>Keine Zuordnung</em> enden alle Verknüpfungen über die Zuordnung; manuelle Verknüpfungen bleiben.</p><ul><li><strong>Wer verknüpft wird:</strong> ein Konto im Status <code>invited</code> oder <code>active</code> ohne manuelle Verknüpfung, wenn <strong>genau ein</strong> aktives Personenelement, das nicht manuell mit einem anderen Konto verknüpft ist, diesen Wert hat und kein anderes Konto dasselbe Attribut hat. Ein Wert, der mehrere Elemente oder mehrere Konten trifft, ergibt <strong>keine Verknüpfung</strong>; die Personenansicht zeigt dann den Konflikt (<code>mappingConflict</code> mit den Element-IDs und der Zahl der Konten). Eine manuelle Verknüpfung hat immer Vorrang, und ein von Hand verknüpftes Element, das ein anderes Konto über die Zuordnung hält, antwortet mit <code>409</code>.</li><li><strong>Folgt den Daten:</strong> Die Verknüpfungen werden im selben Schritt wie das Schreiben des Werts neu berechnet (auch bei Stapelschreibvorgängen, Diagramm-Speichern und wenn eine Lösung live geht), beim Löschen oder Wiederherstellen des Elements (auch per Kaskade), beim Hinzufügen oder Entfernen einer Identitätsbindung, bei einem Statuswechsel eines Kontos und bei einer Änderung der Zuordnung oder des Entitätstyps von Personen. Jede Änderung wird als <code>person.account-linked</code> mit <code>source: mapping</code> protokolliert (eine manuelle mit <code>source: manual</code>).</li><li><strong>Verantwortlichkeiten bleiben bei den Elementen:</strong> Ein Konto zu deaktivieren oder zu offboarden oder seine Identität zu lösen beendet nur die Verknüpfung; das Personenelement und seine <em>Responsible</em>-Verbindungen bleiben unverändert, und die Verknüpfung kehrt zurück, wenn das Konto wieder aktiv ist.</li><li><strong>Die Eigenschaft muss schreibgeschützt sein:</strong> Sie braucht den Sichtbarkeitsmodus <em>Rollenbasiert</em> (sonst <code>422</code> mit <code>propertyDefId</code>), damit nur die gewählten Rollen Werte schreiben, die Konten verknüpfen. Solange sie die Zuordnungseigenschaft ist, kann ihr Modus <em>Rollenbasiert</em> nicht verlassen (<code>422</code> mit <code>visibilityMode</code>). Die Eigenschaft zu löschen oder vom Entitätstyp von Personen zu entfernen löscht die Zuordnung und ihre Verknüpfungen.</li><li><strong>Funktionstrennung:</strong> Eine Anfrage, die <strong>deinem eigenen</strong> Konto eine neue Verknüpfung geben würde – deinen eigenen Wert schreiben, ein Element wiederherstellen, ein Go-live oder eine Identität an dein eigenes Konto binden –, wird mit <code>403</code> abgelehnt, als <code>authz.denied</code> mit dem Grund <code>self-administration</code> protokolliert, und nichts ändert sich. Zusammen mit dem Schreibschutz kann kein Schreibender sein eigenes Konto mit einem Element verknüpfen, das einen Geltungsbereich trägt. Ein Servicekonto mit Schreibrolle schreibt Werte für andere; wähle die Schreibrollen mit Sorgfalt.</li><li>Die Änderung der Zuordnung wird als <code>visibility.person-link-mapping-changed</code> protokolliert. <code>GET</code> und <code>PUT /admin/property-visibility/person-link-mapping</code> lesen (<code>visibility:configure</code> oder <code>person:manage</code>) und setzen (<code>visibility:configure</code>) sie: <code>{&quot;propertyDefId&quot;: &quot;&lt;ID&gt;&quot;, &quot;accountAttribute&quot;: &quot;idp-subject&quot;}</code> oder <code>{&quot;propertyDefId&quot;: null}</code> zum Löschen. <code>GET /admin/persons/{personId}</code> zeigt <code>mappedEntityId</code>, <code>linkSource</code> (<code>manual</code> oder <code>mapping</code>) und <code>mappingConflict</code>; die Verknüpfung, die für die Sichtbarkeit zählt, ist <code>entityId</code>, falls gesetzt, sonst <code>mappedEntityId</code>.</li></ul><h2 id="override-roles" tabindex="-1">Override-Rollen <a class="header-anchor" href="#override-roles" aria-label="Permalink to “Override-Rollen”">​</a></h2><p>Ausnahmen wie eine Fehleranalyse oder eine Datenmigration verlangen manchmal, dass jemand alle eingeschränkten Werte sieht, ohne dass die Leserollen jeder Eigenschaft geändert werden. Dafür setzt die Sicherheitsadministration eine Rolle auf die Override-Liste: Öffne <em>Override-Rollen</em> in der Kopfzeile oder folge dem Link auf der Seite <em>Sichtbarkeit von Eigenschaften</em>.</p>`,9),i(d,{name:`override-roles`,alt:`Override-Rollen mit dem Audit-Hinweis und der Rollenauswahl`}),o[2]||=t(`<ul><li>Hake die Rollen an und wähle <em>Speichern</em>. Nach der Installation ist die Liste leer, und sie fasst höchstens 20 Rollen. Meist nimmst du dafür eine <a href="./roles-and-permissions#custom-roles">eigene Rolle</a> wie <code>migration-support</code> und vergibst sie nur für die Dauer der Arbeit.</li><li>Wer eine Override-Rolle hat, sieht in Katalogen und im Portal jeden Wert und kann danach sortieren und filtern, aber nur bei Entitäten, die ohnehin lesbar sind: Die Override-Rolle gibt keinen Zugriff auf Entitäten und erlaubt nicht, eingeschränkte Werte zu schreiben.</li><li>Jede Abfrage, die einen Wert nur wegen einer Override-Rolle zeigt, schreibt einen Eintrag <code>property-override-access</code> ins Audit-Log, mit den Eigenschaften und den Entitäten, deren Werte gezeigt wurden. Ein Wert, den die Person über eine Leserolle oder eine Verbindung lesen dürfte, zählt nicht.</li><li>Jede Änderung der Liste wird als <code>visibility.override-changed</code> mit alter und neuer Liste im Audit-Log festgehalten; fügst du eine deiner eigenen Rollen hinzu, wird die Änderung als selbstbegünstigend markiert.</li><li>Eine Änderung gilt ab der nächsten Anfrage.</li></ul><h2 id="sichtbarkeit-andern" tabindex="-1">Sichtbarkeit ändern <a class="header-anchor" href="#sichtbarkeit-andern" aria-label="Permalink to “Sichtbarkeit ändern”">​</a></h2><p>Klicke auf den Stift einer Eigenschaft und wähle die Sichtbarkeit:</p><ul><li><strong>Öffentlich:</strong> Alle, die die Entität lesen dürfen, sehen den Wert. Das ist der Standard jeder Eigenschaft.</li><li><strong>Rollenbasiert:</strong> Nur Inhaber der gewählten Leserollen sehen den Wert, und nur Inhaber der gewählten Schreibrollen dürfen ihn ändern. Wähle mindestens eine Leserolle; jede Schreibrolle muss auch eine Leserolle sein. Ohne Schreibrolle darf niemand den Wert ändern.</li><li><strong>Verbindungsbasiert:</strong> Nur Personen, die über den gewählten Verbindungstyp mit der Entität verbunden sind, sehen und ändern den Wert, zum Beispiel eine Domänenarchitektin, die über <em>Domain Assignment</em> verbunden ist. Wählbar sind nur Verbindungstypen.</li></ul><p>Der Dialog zeigt nur die Felder der gewählten Sichtbarkeit und weist auf eine fehlende Auswahl hin, bevor er speichert. Jede Änderung wird als <code>visibility.changed</code> ins Audit-Log geschrieben; eine Änderung, die eine deiner eigenen Rollen begünstigt, wird als selbstbegünstigend markiert.</p><p>Solange ein Verbindungstyp für eine verbindungsbasierte Eigenschaft verwendet wird, braucht das Anlegen von Verbindungen dieses Typs die Berechtigung <code>visibility-scope:assign</code> (Rolle <code>security-admin</code>), damit sich niemand selbst Zugriff verschafft. Ein solcher Verbindungstyp lässt sich nicht löschen.</p><p>In der Metamodell-Konfiguration tragen eingeschränkte Eigenschaften das Badge <em>Eingeschränkt</em>, und der Dialog einer Eigenschaft zeigt ihre Sichtbarkeit nur lesend (siehe <a href="./metamodel-editing">Metamodell bearbeiten</a>).</p><h2 id="change-history" tabindex="-1">Änderungshistorie <a class="header-anchor" href="#change-history" aria-label="Permalink to “Änderungshistorie”">​</a></h2><p>Die <a href="./../usage/change-history">Änderungshistorie</a> einer Entität nennt die Felder, die jede Version geändert hat, nie ihre Werte. Für ein Feld, das die lesende Person nicht lesen darf, entscheidet der Abschnitt <em>Änderungshistorie</em> unter der Liste, wie es erscheint:</p><ol><li>Wähle den Entitätstyp.</li><li>Wähle für jede Rolle <em>Eingeschränkt</em> (das Feld erscheint mit dem Badge <em>Eingeschränkt</em>) oder <em>Ausgeblendet</em> (das Feld fehlt).</li><li>Wähle <em>Speichern</em>. Nur die geänderten Rollen werden gespeichert; ein abgelehnter Eintrag wird in seiner Zeile markiert, und dann wird nichts gespeichert.</li></ol><p>Ohne Einstellung zeigt jede Rolle <em>Eingeschränkt</em>. Eine Person mit mehreren Rollen sieht die offenere Einstellung: Das Feld fehlt nur, wenn jede ihrer Rollen es für den Entitätstyp ausblendet. Eine Einstellung gilt für genau einen Entitätstyp, nicht für seine Untertypen, und ein Paketimport behält sie. Jeder geänderte Eintrag wird als <code>visibility.history-changed</code> ins Audit-Log geschrieben; eine eigene Rolle wieder auf <em>Eingeschränkt</em> zu setzen wird als selbstbegünstigend markiert.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><p><code>GET /admin/property-visibility</code> listet die Sichtbarkeit jeder Eigenschaft mit <code>visibilityMode</code>, <code>readRoles</code>, <code>writeRoles</code>, <code>scopingConnectionType</code> und den Entitätstypen in <code>metatypes</code>.</p></li><li><p><code>PUT /admin/property-visibility</code> ändert die aufgeführten Eigenschaften in einem Schritt, zum Beispiel:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --arg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[{propertyDefId: $id, visibilityMode: &quot;role-restricted&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  readRoles: [&quot;enterprise-architect&quot;, &quot;auditor&quot;], writeRoles: [&quot;enterprise-architect&quot;]}]&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/property-visibility&quot;</span></span></code></pre></div><p>Ein ungültiger Eintrag antwortet mit <code>422</code> und dem Feld in <code>invalidFields</code>, etwa <code>[0].readRoles</code>, und nichts wird geändert.</p></li><li><p><code>GET</code> und <code>PUT /admin/property-visibility/person-metatype</code> lesen und setzen den Entitätstyp von Personen, zum Beispiel <code>{&quot;metatypeId&quot;: &quot;&lt;ID des Entitätstyps&gt;&quot;}</code>, oder <code>{&quot;metatypeId&quot;: null}</code> für keinen. Ein Verbindungstyp oder ein unbekannter Entitätstyp antwortet mit <code>422</code> und <code>metatypeId</code> in <code>invalidFields</code>.</p></li><li><p><code>GET</code> und <code>PUT /admin/property-visibility/override-roles</code> lesen und ersetzen die Override-Rollen, zum Beispiel <code>{&quot;roles&quot;: [&quot;migration-support&quot;]}</code>. Eine unbekannte Rolle antwortet mit <code>422</code> und <code>roles</code> in <code>invalidFields</code>; mehr als 20 Rollen antworten mit <code>400</code>.</p></li><li><p><code>GET</code> und <code>PUT /admin/history-visibility</code> lesen und ändern die Einstellungen der Änderungshistorie, zum Beispiel <code>{&quot;entries&quot;: [{&quot;roleId&quot;: &quot;viewer&quot;, &quot;metatypeId&quot;: &quot;&lt;ID des Entitätstyps&gt;&quot;, &quot;mode&quot;: &quot;hide&quot;}]}</code>. <code>show-restricted</code> entfernt einen Eintrag. Eine Änderung enthält 1 bis 500 Einträge; eine unbekannte Rolle, ein unbekannter Entitätstyp oder Modus antwortet mit <code>422</code> und dem Eintrag in <code>invalidFields</code>, etwa <code>entries[0].roleId</code>, und nichts wird geändert.</p></li></ul><p>Alle brauchen <code>visibility:configure</code>.</p>`,14)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};